const D = (h, ...d) => ({ h, d });
const B = (h, tx, cls = 'why') => ({ h, tx, cls });
const P = (img, cap) => ({ img, cap });
const CH = ['Termoreglarea', 'Febra', 'Hodgkin și angina streptococică', 'Inflamația'];
const chap = (n) => (n <= 9 ? CH[0] : n <= 15 ? CH[1] : n <= 20 ? CH[2] : CH[3]);
// numărul de cuvinte din răspunsul model (fără marcaje)
const wc = (ans) => ans.map((p) => (p.d && p.d[0]) || p.h).join(' ').replace(/\*\*|!!/g, '').split(/\s+/).filter((w) => /[\p{L}\p{N}]/u.test(w)).length;
// întrebarea → 2 slide-uri
function Q(n, o) {
  const k = `Întrebarea ${n} · ${chap(n)}`;
  const words = wc(o.ans); const min = Math.max(1, Math.round(words / 25));
  return [
    { scene: `q${n}`, kick: `${k} · Înțelege`, title: o.head, hud: [`Î ${n} din 22`, o.hud || 'mecanismul'], points: o.pts,
      anim: o.anim !== false, spec: o.spec, xtra: o.xtra,
      boxes: [...(o.dense ? [] : [B('Ideea-cheie', o.idea)]), B('Întrebarea de examen', o.q, 'say')], insets: o.ins, beatDur: 6.5 },
    { scene: 'foaie', sceneOpts: { n, words, min }, kick: `${k} · Răspuns model`, title: o.q, hud: [`~${words} cuvinte · ~${min} min de scris`],
      anim: false, spec: 'foaia de răspuns: frazele răspunsului model apar pe rând, cuvintele de punctaj se evidențiază cu galben',
      points: o.ans, compact: true, boxes: [B('Cuvintele de punctaj', o.kw.map((w) => (w.startsWith('!!') ? w : `**${w}**`)).join(' · ')), B('Ține minte', o.mn, 'say'), ...(o.warn ? [B('Atenție', o.warn, 'warn')] : [])], insets: o.ansIns || [null], beatDur: 6 },
  ];
}

